 if(w.step===1){html='<p class="wizard-caption">PARTY SIZE · ROTATION = PEOPLE ÷ 4, ROUNDED UP</p><div class="people-pick-grid">'+Array.from({length:20},(_,i)=>`<button class="pick-btn ${w.people===i+1?'selected':''}" data-people="${i+1}">${i+1}</button>`).join('')+`</div><label for="wizardPeople">Number of guests</label><input id="wizardPeople" class="field" type="number" min="1" max="120" value="${w.people}"><div class="secondary-box"><b>Secondary tables · optional</b>${secondaryChoices(w.secondary,w.table)}</div>`;}
 if(w.step===2){html='<label for="serverSearch" class="sr-only">Search server name</label><input id="serverSearch" class="field" placeholder="Search server name…"><p class="wizard-caption">3 NAMES PER ROW · FORMATION SERVERS</p><div class="wizard-server-grid">'+C.list(shiftBoard()?.rows).filter(r=>!r.cut).map(r=>`<button class="pick-btn server-pick ${r.id===w.rowId?'selected':''}" data-server="${esc(r.id)}"><strong>${esc(r.server)}</strong><small>Section ${esc(r.section)} · Beeper ${esc(r.beeper||'—')}</small></button>`).join('')+'</div>'+`<div class="review"><div><span>TABLE</span><b>${esc(w.table)}</b></div><div><span>GUESTS</span><b>${w.people}</b></div><div><span>SECONDARY</span><b>${esc(w.secondary.join(', ')||'None')}</b></div></div>`;}
 $('wizardBody').innerHTML=html;if($('serverSearch'))$('serverSearch').oninput=()=>{$('wizardBody').querySelectorAll('[data-server]').forEach(button=>button.hidden=!button.textContent.toLowerCase().includes($('serverSearch').value.trim().toLowerCase()));};
