function sectionOrder(a,b){const key=r=>String(r.section).split(/\s*\/\s*/).filter(s=>!/^BAR$/i.test(s)).sort((x,y)=>x.localeCompare(y,undefined,{numeric:true}))[0]||'ZZZ';return key(a).localeCompare(key(b),undefined,{numeric:true});}
function nextRow(){return C.list(shiftBoard()?.rows).filter(r=>!r.cut&&C.slots(r)<60).sort((a,b)=>C.slots(a)-C.slots(b)||sectionOrder(a,b))[0]||null;}
function renderBoard(){const b=shiftBoard();if(!b)return false;const renderKey=JSON.stringify([selectedShift,b,state.tables]);if(lastBoardRenderKey===renderKey)return false;lastBoardRenderKey=renderKey;const next=nextRow(),active=b.rows.filter(r=>!r.cut).sort(sectionOrder);$('nextName').textContent=next?.server||'—';$('nextMeta').textContent=next?'SECTION '+next.section+' · '+next.entries.filter(e=>e.kind==='party').length+' TABLES · BEEPER '+(next.beeper||'—'):'Set a formation to begin';const available=next?config.tables.filter(t=>b.assignments[t.id]===next.id&&state.tables[t.id].status==='ready'):[];$('nextReady').textContent=next?'READY TABLES · '+available.length+' AVAILABLE · '+(available.map(t=>t.id).join(' · ')||'None'):'';$('seatNext').disabled=!next||!connection?.connected||connection.busy;$('seatNext').onclick=()=>openSeatWizard({rowId:next?.id||''});$('teamCount').textContent=active.length+' active';
 $('boardRows').innerHTML=active.length?active.map(r=>{const cells=r.entries.flatMap(e=>e.kind==='party'?[`<button class="turn party" data-party-table="${esc(e.primary)}" title="${esc(e.primary)} · ${e.people} guests"><b>${esc(e.primary)}</b><small>${e.people} guests</small></button>`,...Array.from({length:Math.ceil(e.people/4)-1},()=>`<button class="turn party continuation" data-party-table="${esc(e.primary)}" title="${esc(e.primary)} · ${e.people} guests · same party"><b>${esc(e.primary)}</b><small>same party</small></button>`)]:[`<button class="turn ${e.kind}" ${e.kind==='manual'?`data-unskip="${esc(e.id)}" data-row="${esc(r.id)}"`:''} title="${e.kind==='auto'?'BAR AUTO':'MANUAL'} SKIP"><b>SKIP</b></button>`]);const used=cells.length,shown=Math.max(45,Math.ceil(used/15)*15);while(cells.length<shown)cells.push(`<div class="turn empty ${cells.length===used?'current':''}" aria-label="Empty turn ${cells.length+1}"></div>`);return `<article class="board-row ${r.cut?'cut':''} ${r===next?'next':''}"><div class="row-meta"><span class="section-bubble">${esc(r.section==='BAR'?'BAR':'S'+r.section)}</span><div><strong>${esc(r.server)}</strong><small>${r.entries.filter(e=>e.kind==='party').length} tables · ${used} turns${r.cut?' · CUT':''}</small><span class="beeper-chip">BEEPER ${esc(r.beeper||'—')}</span><span class="work-shift-chip">${esc(r.workShift||selectedShift)}${r.workShift==='Long Shift'?' · '+esc(r.longStart||'14:00'):''}</span><small class="cut-advice">${esc(C.cutAdvice(state,selectedShift,r,connection.now()).label)}</small></div></div><div class="turns">${cells.join('')}</div><div class="row-actions"><button class="row-seat" data-row-seat="${esc(r.id)}" ${r.cut?'disabled':''}>SEAT</button><button class="row-skip" data-skip="${esc(r.id)}">SKIP</button><button class="row-floor" data-row-floor="${esc(r.id)}">FLOOR</button><button class="row-clear danger" data-row-clear="${esc(r.id)}">CLEAR</button>${selectedShift==='PM'&&String(r.section).toUpperCase().includes('BAR')?`<button class="bar-toggle ${r.barAuto!==false?'on':'off'}" data-bar-toggle="${esc(r.id)}" data-bar-next="${r.barAuto===false}" aria-pressed="${r.barAuto!==false}">AUTO SKIP ${r.barAuto!==false?'ON':'OFF'}</button>`:''}</div></article>`;}).join(''):'<div class="empty-state"><h3>No active servers.</h3><p>Use Cut / Uncut Employee to restore a server, or set Formation &amp; Servers for a new shift.</p><button class="primary" data-op="setup">FORMATION &amp; SERVERS</button></div>';
 $('boardRows').querySelectorAll('[data-row-clear]').forEach(b=>b.onclick=()=>clearBoardEntryDialog(b.dataset.rowClear));$('boardRows').querySelectorAll('[data-skip]').forEach(b=>b.onclick=()=>{const answer=prompt('How many skips? (1–60)','1');if(answer===null)return;const count=Number(answer);if(!Number.isInteger(count)||count<1||count>60)return toast('Enter 1–60 skips.');void send('SKIP',{rowId:b.dataset.skip,count},{message:count+' MANUAL SKIP'+(count===1?'':'S')+' ADDED'}).catch(()=>{});});$('boardRows').querySelectorAll('[data-unskip]').forEach(b=>b.onclick=()=>{if(requireManager())void send('SKIP',{rowId:b.dataset.row,entryId:b.dataset.unskip},{message:'MANUAL SKIP REMOVED'}).catch(()=>{});});$('boardRows').querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>operation(b.dataset.op));$('boardRows').querySelectorAll('[data-bar-toggle]').forEach(b=>b.onclick=()=>send('ROW_EDIT',{rowId:b.dataset.barToggle,barAuto:b.dataset.barNext==='true'},{message:'BAR AUTO SKIP '+(b.dataset.barNext==='true'?'ON':'OFF')}).catch(()=>{}));$('boardRows').querySelectorAll('[data-row-seat]').forEach(b=>b.onclick=()=>openSeatWizard({rowId:b.dataset.rowSeat}));$('boardRows').querySelectorAll('[data-row-floor]').forEach(b=>b.onclick=()=>pane('floor'));$('boardRows').querySelectorAll('[data-party-table]').forEach(b=>b.onclick=()=>{pane('floor');$('map').querySelector('[data-table="'+b.dataset.partyTable+'"]').click();});}
function render(){if(!state||!config)return;$('logout').textContent=(manager()?role.toUpperCase()+' ':'')+'LOG OUT';$('day').textContent=state.day;$('shiftBadge').textContent=selectedShift;renderMap();renderPanel();if(renderBoard()!==false)renderFrontiers();}
function clearBoardEntryDialog(rowId){const row=shiftBoard()?.rows.find(r=>r.id===rowId);if(!row)return;const entries=row.entries.filter(e=>e.kind==='party');openDialog('Clear Wrong Table',`<p class="helper">${esc(row.server)} · ${esc(selectedShift)}. Choose the incorrect Board entry. Active party tables become READY. Undo Delete can restore it.</p>${entries.map((e,i)=>`<button class="full danger" data-clear-entry="${esc(e.id)}">CLEAR ${esc(e.primary)} · ${e.people} guests · Entry ${i+1}${state.parties[e.id]?' · ACTIVE':' · BOARD ONLY'}</button>`).join('')||'<p>No table entries to clear.</p>'}`);$('modalBody').querySelectorAll('[data-clear-entry]').forEach(button=>{const entry=row.entries.find(e=>e.id===button.dataset.clearEntry),partyVersion=state.parties[entry.id]?.version||null;button.onclick=()=>{if(confirm('Clear '+entry.primary+' from '+row.server+'? Active party and secondary tables become READY.'))void send('CLEAR_ENTRY',{rowId,entryId:entry.id,partyVersion},{message:'WRONG TABLE CLEARED · UNDO AVAILABLE'}).catch(()=>{});};});}
function openPartyEdit(p,moving){const frozen=partyValues(p);openDialog(moving?'Move / Change Party':'Edit Secondary',`<p class="helper">${esc(p.primary)} · ${p.people} guests · ${esc(currentRow(p)?.server)}</p>${moving?`<label for="newPrimary">Move to table</label><select id="newPrimary" class="field">${config.tables.filter(t=>state.tables[t.id].status==='ready'||C.members(p).includes(t.id)).map(t=>`<option ${t.id===p.primary?'selected':''}>${esc(t.id)}</option>`).join('')}</select><label for="newServer">Server · keep the same unless changing employee</label><select id="newServer" class="field">${rowOptions(p.rowId)}</select><p id="movePreview" class="panel-info" role="status"></p><p class="helper">To add or remove joined tables, use Edit Secondary.</p>`:`<label>Secondary tables</label><div id="secondaryOptions">${secondaryChoices(C.list(p.secondary),p.primary)}</div>`}<button id="savePartyEdit" class="primary full">SAVE ${moving?'MOVE / CHANGE':'SECONDARY'}</button>`);
 if(moving){const preview=()=>{const target=$('newPrimary').value;$('movePreview').textContent=target===p.primary?'Current table: '+p.primary+'. Choose a destination to move, or change the server.':'MOVE '+p.primary+' → '+target+'. '+p.primary+' becomes READY. Existing secondary tables stay linked.';};$('newPrimary').onchange=preview;preview();}
 $('savePartyEdit').onclick=()=>{const target=moving?$('newPrimary').value:p.primary,rowId=moving?$('newServer').value:p.rowId;if(moving&&target===p.primary&&rowId===p.rowId)return toast('Choose a destination table or change the server.');if(moving&&!rowId)return toast('Choose the server.');void send(moving?'MOVE':'SECONDARY',{...frozen,...(moving?{target,rowId}:{}),secondary:moving?C.list(p.secondary).filter(id=>id!==target&&id!==p.primary):checkedSecondary($('modalBody'))},{message:moving?'PARTY MOVED · OLD TABLE READY':'SECONDARY TABLES UPDATED'}).then(()=>{if(moving){selected=target;lastPanel='';renderMap();renderPanel();}}).catch(()=>{});};}

const operations=[['setup','Formation & Servers','Choose formation and assign your servers.'],['join','Breaking Section','Split tables to a new server at the end of rotation.'],['beeper','Beeper','Assign and verify beepers 1–20.'],['map','Edit Table Map','Change tables inside a formation section.'],['formation','Edit Formation','Edit formation structure and current server rows.'],['correct','Correct Wrong AM / PM','Move this shift and its Floor links together.'],['roster','Manage Server List','Add or delete names in the shared server list.'],['cut','Cut / Uncut Employee','Manage active rotation employees.'],['reservations','Reservations','Create and manage upcoming reservations.'],['chat','Manager Chat / VN / Call','Messages, voice notes and live calls.'],['shout','Team Shout Out','Send a large announcement to connected devices.'],['password','Edit Manager Password','Update the shared manager gate.'],['bar','Repair BAR · Auto SKIP','Convert matching manual skips to automatic skips.'],['undo','Undo Delete','Restore a deleted party and its secondary tables.'],['pending','Recheck Pending Operation','Resolve a save whose connection was interrupted.'],['clearAM','Clear Board + Shift AM','Clear AM Board, formation, parties, skips and Undo.'],['clearPM','Clear Board + Shift PM','Clear PM Board, formation, parties, skips and Undo.']];
function operation(name){if(!state||!config)return toast('Wait until the database is ready.');$('seatWizard').close();if(['map','formation','correct','cut','shout','password','bar','clearAM','clearPM','roster'].includes(name)&&!requireManager())return;
 if(name==='roster')return rosterDialog();if(name==='setup')return setupDialog();if(name==='join')return joinDialog();if(name==='beeper')return beeperDialog();if(name==='cut')return cutDialog();if(name==='map')return mapDialog();if(name==='formation')return formationDialog();if(name==='reservations')return reservationDialog();if(name==='chat')return communications.openChat();
 if(name==='correct'){if(confirm('Correct '+selectedShift+' to '+(selectedShift==='AM'?'PM':'AM')+'?\n\nThe other shift must be empty. Party and secondary links move together.'))void send('CORRECT',{}, {message:'SHIFT CORRECTED'}).then(r=>{if(r){selectedShift=selectedShift==='AM'?'PM':'AM';$('shift').value=selectedShift;lastPanel='';render();}}).catch(()=>{});return;}
 if(name==='clearAM'||name==='clearPM'){const shift=name==='clearAM'?'AM':'PM';if(confirm('CLEAR BOARD + SHIFT '+shift+'?\n\nRemove '+shift+' formation, servers, Board entries, party tables, skips and Undo. The other shift stays unchanged. Reservations and server list remain.'))void send('CLEAR_SHIFT',{shift},{message:'BOARD + SHIFT '+shift+' CLEARED'}).catch(()=>{});return;}
 if(name==='undo'){const records=Object.values(state.undo).sort((a,b)=>b.at-a.at);const readyRecords=['AM','PM'].flatMap(sh=>C.list(state.shifts[sh]?.rows).flatMap(r=>r.entries.filter(e=>e.kind==='party'&&!state.parties[e.id]&&[e.primary,...C.list(e.secondary)].every(t=>state.tables[t]?.status==='ready')).map(e=>({sh,r,e})))).sort((a,b)=>b.e.at-a.e.at).slice(0,25);openDialog('Undo Delete / Wrong Ready','<h3>Deleted parties</h3>'+ (records.map(u=>`<button class="full" data-undo="${esc(u.id)}">RESTORE ${esc(C.members(u.party).join(' + '))} · ${u.party.people} guests · ${esc(u.shift)}</button>`).join('')||'<p class="helper">No deleted parties.</p>')+'<h3>Restore Wrong Ready · existing Board record</h3><p class="helper">Choose the original party. This restores Floor occupancy without adding another turn.</p>'+ (readyRecords.map(({sh,r,e})=>`<button class="full" data-restore-ready="${esc(e.id)}" data-row="${esc(r.id)}" data-shift="${sh}">RESTORE ${esc([e.primary,...C.list(e.secondary)].join(' + '))} · ${esc(r.server)} · ${e.people} guests · ${sh} · ${esc(new Date(e.at).toLocaleTimeString('en-US',{timeZone:'America/Chicago',hour:'numeric',minute:'2-digit'}))}</button>`).join('')||'<p class="helper">No released parties with all tables READY.</p>'));$('modalBody').querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>send('UNDO',{undoId:b.dataset.undo},{message:'PARTY + BOARD RESTORED'}).catch(()=>{}));$('modalBody').querySelectorAll('[data-restore-ready]').forEach(b=>b.onclick=()=>{if(confirm(b.textContent+'?\n\nRestore this original party to the Floor without adding a turn?'))void send('RESTORE_READY',{shift:b.dataset.shift,rowId:b.dataset.row,entryId:b.dataset.restoreReady},{message:'WRONG READY UNDONE · ORIGINAL PARTY RESTORED'}).catch(()=>{});});return;}
 if(name==='pending'){notice('Rechecking the same operation ID…','saving');void connection.recoverPending().then(()=>{notice('Pending operation resolved.');toast('Operation rechecked.');}).catch(e=>{notice(e.message,'error');toast(e.message);});return;}
 if(name==='bar'){openDialog('Repair BAR Manual → Auto SKIP',`<p class="helper">Matching manual SKIPs after each two BAR parties become automatic. Other manual SKIPs stay.</p><select id="barRow" class="field">${rowOptions('',true)}</select><button class="primary full" id="barRepair">REPAIR PM BAR</button>`);$('barRepair').onclick=()=>send('BAR_REPAIR',{rowId:$('barRow').value},{message:'BAR AUTO SKIP REPAIRED'}).catch(()=>{});return;}
 if(name==='shout'){openDialog('Team Shout Out','<label for="shoutText">Message</label><textarea id="shoutText" class="field" maxlength="400"></textarea><button id="sendShout" class="primary full">SEND TO CONNECTED HOSTS</button>');$('sendShout').onclick=async()=>{try{const text=$('shoutText').value.trim();if(!text)return;await connection.ref.child('shout').set({id:HostCore.uid(),text,at:connection.now(),expiresAt:connection.now()+120000,from:role});closeDialog();toast('SHOUT SENT');}catch(e){toast(e.message);}};return;}
 if(name==='password')return passwordDialog();}
async function addServerName(value){const name=C.canonical(value);if(!name||name.length>100)throw Error('Enter a server name, up to 100 characters.');await connection.updateConfig(c=>{c.servers=C.list(c.servers);if(!c.servers.some(s=>s.toLowerCase()===name.toLowerCase()))c.servers.push(name);return c;});return name;}
function rosterDialog(){openDialog('Manage Server List',`<label for="newServerName">New server name</label><input id="newServerName" class="field" maxlength="100"><button id="addServerName" class="primary full">ADD NEW SERVER</button><p class="helper">Changes apply to the shared employee list. Current shift rows and seated parties stay unchanged.</p><label for="deleteServerName">Delete name from employee list</label><select id="deleteServerName" class="field"><option value="">Choose a server…</option>${config.servers.slice().sort((a,b)=>a.localeCompare(b)).map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('')}</select><button id="deleteServerNameAction" class="danger full">DELETE SERVER NAME</button>`);$('addServerName').onclick=async()=>{try{const name=await addServerName($('newServerName').value);rosterDialog();toast('SERVER ADDED · '+name);}catch(e){toast(e.message);}};$('deleteServerNameAction').onclick=async()=>{const name=$('deleteServerName').value;if(!name)return toast('Choose a server name.');if(!confirm('Delete '+name+' from the employee list? Current shift rows and seated parties will remain.'))return;const button=$('deleteServerNameAction');button.disabled=true;try{await connection.updateConfig(c=>{c.servers=C.list(c.servers).filter(s=>s!==name);return c;});rosterDialog();toast('SERVER NAME DELETED · '+name);}catch(e){button.disabled=false;toast(e.message);}};}

function setupDialog(){openDialog('Formation & Servers',`<p class="helper">Save each section when its employee arrives. Other sections can stay empty.</p><label for="setupFormation">Formation</label><select id="setupFormation" class="field">${Object.keys(config.formations).map(k=>`<option value="${esc(k)}" ${k===shiftBoard()?.formation?'selected':''}>${esc(formationLabel(k))}</option>`).join('')}</select><div id="sectionAssignments"></div>${cutRulesHTML()}<details class="new-server-box"><summary>+ ADD NEW SERVER</summary><label for="setupNewServer">New server name</label><input id="setupNewServer" class="field" maxlength="100"><button id="setupAddServer" class="full">ADD SERVER NAME</button></details>`);const draw=()=>{$('sectionAssignments').innerHTML=Object.keys(config.formations[$('setupFormation').value]).map(sec=>{const owner=shiftBoard()?.formation===$('setupFormation').value?shiftBoard().rows.find(r=>!r.cut&&r.section.split(' / ').includes(sec)):null;const names=[...new Set([...config.servers,...(owner?[owner.server]:[])])];return `<div class="form-row arrival-section"><label>SECTION ${esc(sec)}</label><select class="field" data-section="${esc(sec)}" data-owner="${esc(owner?.id||'')}"><option value="">Choose employee…</option>${names.map(name=>`<option value="${esc(name)}" ${name===owner?.server?'selected':''}>${esc(name)}</option>`).join('')}</select><div class="arrival-settings"><label>Beeper<select class="field" data-arrival-beeper><option value="">None</option>${Array.from({length:20},(_,i)=>`<option value="${i+1}" ${String(i+1)===owner?.beeper?'selected':''}>${i+1}</option>`).join('')}</select></label><label>Shift<select class="field" data-arrival-shift>${['AM','PM','Double','Long Shift'].map(type=>`<option value="${type}" ${type===(owner?.workShift||selectedShift)?'selected':''}>${type==='Double'?'Double Shift':type}</option>`).join('')}</select></label><label>Long start<input type="time" class="field" data-arrival-start value="${esc(owner?.longStart||'14:00')}"></label><label class="last-cut-choice"><input type="checkbox" data-arrival-last ${owner?.lastCut?'checked':''}> PM last cut</label></div><button class="primary" data-save-section="${esc(sec)}">SAVE</button><span class="arrival-status">${owner?'SAVED · '+esc(owner.server):'Not assigned yet'}</span></div>`;}).join('');$('sectionAssignments').querySelectorAll('[data-save-section]').forEach(button=>button.onclick=async()=>{const sec=button.dataset.saveSection,select=button.parentElement.querySelector('select');if(!select.value)return toast('Choose an employee who has arrived.');button.disabled=true;try{const result=await send('SECTION_SERVER',{formation:$('setupFormation').value,section:sec,server:select.value,expectedOwner:select.dataset.owner,beeper:button.parentElement.querySelector('[data-arrival-beeper]').value,workShift:button.parentElement.querySelector('[data-arrival-shift]').value,longStart:button.parentElement.querySelector('[data-arrival-start]').value,lastCut:button.parentElement.querySelector('[data-arrival-last]').checked},{keepDialog:true,message:'SECTION '+sec+' SAVED · '+select.value});if(result){const owner=shiftBoard().rows.find(r=>!r.cut&&r.section.split(' / ').includes(sec));select.dataset.owner=owner?.id||'';button.parentElement.querySelector('.arrival-status').textContent='SAVED · '+owner?.server;}}catch(_){}finally{button.disabled=false;}});};$('sectionAssignments').addEventListener('change',event=>{const select=event.target;if(!select.matches('[data-section]'))return;const box=select.parentElement,row=shiftBoard().rows.find(r=>!r.cut&&r.server===select.value);box.querySelector('[data-arrival-beeper]').value=row?.beeper||'';box.querySelector('[data-arrival-shift]').value=row?.workShift||selectedShift;box.querySelector('[data-arrival-start]').value=row?.longStart||'14:00';box.querySelector('[data-arrival-last]').checked=!!row?.lastCut;});$('setupFormation').onchange=draw;draw();$('setupAddServer').onclick=async()=>{try{const name=await addServerName($('setupNewServer').value);if(!name)return;for(const select of $('sectionAssignments').querySelectorAll('[data-section]'))if(![...select.options].some(o=>o.value===name)){const option=document.createElement('option');option.value=name;option.textContent=name;select.appendChild(option);}$('setupNewServer').value='';toast('SERVER ADDED · '+name);}catch(e){toast(e.message);}};}

function joinDialog(){openDialog('Breaking Section',`<label for="joinServer">Arriving server</label><input id="joinServer" class="field" list="employeeNames"><datalist id="employeeNames">${config.servers.map(s=>`<option value="${esc(s)}">`).join('')}</datalist><label for="joinSection">Section label</label><input id="joinSection" class="field" placeholder="e.g. 4B"><label>Transfer these table assignments</label><div class="secondary-grid">${config.tables.map(t=>`<label class="secondary-choice"><input type="checkbox" name="joinTable" value="${esc(t.id)}">${esc(t.id)}</label>`).join('')}</div><p class="helper">The new employee joins at the end of the rotation. Existing parties keep their original server.</p><button id="saveJoin" class="primary full">BREAK SECTION + ADD SERVER</button>`);$('saveJoin').onclick=()=>send('JOIN',{server:$('joinServer').value,section:$('joinSection').value,tables:[...$('modalBody').querySelectorAll('[name=joinTable]:checked')].map(x=>x.value)},{message:'SECTION SPLIT · SERVER ADDED TO ROTATION END'}).catch(()=>{});}
function beeperDialog(){openDialog('Beeper',C.list(shiftBoard()?.rows).map(r=>`<div class="form-row"><label>${esc(r.server)}</label><select data-beeper="${esc(r.id)}"><option value="">No beeper</option>${Array.from({length:20},(_,i)=>`<option value="${i+1}" ${String(i+1)===r.beeper?'selected':''}>${i+1}</option>`).join('')}</select></div>`).join('')||'<p>Set Formation & Servers first.</p>');$('modalBody').querySelectorAll('[data-beeper]').forEach(e=>e.onchange=()=>send('BEEPER',{rowId:e.dataset.beeper,beeper:e.value},{keepDialog:true,message:'BEEPER CONFIRMED'}).catch(()=>{}));}
function cutRulesHTML(){const day=new Date(state.day+'T12:00:00Z').getUTCDay(),extra=day===0||day>=5?2:1;return `<details class="cut-rules"><summary>CUT RULES · ${extra} extra PM section${extra>1?'s':''} for last cut</summary><p>Double AM: Mon–Thu 3:30 PM; Fri–Sun 3:00 PM. If a Long 2 PM employee has arrived: 2:00 PM.</p><p>PM Double / Long: Mon–Thu + Sun 8:30 PM; Fri–Sat 9:30 PM. PM employees: Mon–Thu + Sun 9:00 PM; Fri–Sat 10:00 PM.</p><p>BAR remains last cut. Section 1 stays last in PM. Select ${extra} extra PM section${extra>1?'s':''} using PM last cut. Manager confirms each CUT.</p></details>`;}
function cutDialog(){const rows=C.list(shiftBoard()?.rows),extra=rows.filter(r=>!r.cut&&r.lastCut&&!String(r.section).includes('BAR')&&!r.section.split(' / ').includes('1'));openDialog('Cut / Uncut Employee',cutRulesHTML()+`<p class="helper">Extra PM last-cut sections selected: ${extra.map(r=>esc(r.section)).join(', ')||'None'}</p>`+rows.map(r=>{const advice=C.cutAdvice(state,selectedShift,r,connection.now());return `<div class="form-row"><label><b>${esc(r.server)} · ${esc(r.section)}</b><br>${esc(r.workShift||selectedShift)} · ${esc(advice.label)}</label><button data-cut="${esc(r.id)}" data-value="${r.cut?'false':'true'}" class="${r.cut?'primary':advice.due?'danger':''}">${r.cut?'UNCUT':advice.due?'CUT DUE · CONFIRM':'CUT EMPLOYEE'}</button></div>`;}).join(''));$('modalBody').querySelectorAll('[data-cut]').forEach(button=>button.onclick=()=>{const row=rows.find(r=>r.id===button.dataset.cut);if(button.dataset.value==='true'&&!confirm('CUT '+row.server+'? '+C.cutAdvice(state,selectedShift,row,connection.now()).label))return;void send('CUT',{rowId:button.dataset.cut,cut:button.dataset.value==='true'},{keepDialog:true,message:'EMPLOYEE STATUS CONFIRMED'}).then(cutDialog).catch(()=>{});});}

function formationDialog(){const original=shiftBoard(),expectedRows=original.rows.map(r=>[r.id,r.server,r.section,r.cut]);openDialog('Edit Formation',`<p class="helper">Choose the new formation and assign each section. Rotation, parties, SKIPs and beepers follow the same server. Unassigned servers remain CUT with their existing entries.</p><label for="changeFormation">Formation</label><select id="changeFormation" class="field">${Object.keys(config.formations).map(k=>`<option value="${esc(k)}" ${k===original.formation?'selected':''}>${esc(formationLabel(k))}</option>`).join('')}</select><div id="changeFormationRows"></div><button id="saveFormationChange" class="primary full">SAVE FORMATION · KEEP ROTATION</button>`);const draw=()=>{const form=config.formations[$('changeFormation').value],names=[...new Set([...original.rows.map(r=>r.server),...config.servers])];$('changeFormationRows').innerHTML=Object.entries(form).map(([sec,ids])=>{const owner=original.rows.find(r=>!r.cut&&r.section.split(' / ').includes(sec));return `<div class="form-row"><div><b>SECTION ${esc(sec)}</b><p class="helper">${esc(C.list(ids).join(', '))}</p></div><select class="field" data-change-section="${esc(sec)}"><option value="">No server</option>${names.map(name=>`<option value="${esc(name)}" ${name===owner?.server?'selected':''}>${esc(name)}</option>`).join('')}</select></div>`;}).join('');};$('changeFormation').onchange=draw;draw();$('saveFormationChange').onclick=()=>send('FORMATION',{formation:$('changeFormation').value,expectedRows,servers:Object.fromEntries([...$('changeFormationRows').querySelectorAll('select')].map(x=>[x.dataset.changeSection,x.value]))},{message:'FORMATION UPDATED · SERVER ROTATION RETAINED'}).catch(()=>{});}
function mapDialog(){let draft={},base='',dirty=false;openDialog('Edit Table Map',`<p class="helper">Choose a formation and target section, then tap a table to move it there. Choose UNASSIGNED to remove a table from its section.</p><label for="mapTemplate">Formation</label><select id="mapTemplate" class="field">${Object.keys(config.formations).map(k=>`<option value="${esc(k)}" ${k===shiftBoard()?.formation?'selected':''}>${esc(formationLabel(k))}</option>`).join('')}</select><label for="mapSection">Move table to</label><select id="mapSection" class="field"></select><div id="mapSectionSummary"></div><div id="mapTableChoices"></div><button id="reloadMap" class="full">RELOAD SAVED</button><button id="saveTemplate" class="primary full">SAVE FORMATION TABLES</button>`);
const draw=()=>{const owner=id=>Object.keys(draft).find(sec=>draft[sec].includes(id));$('mapSectionSummary').innerHTML=Object.entries(draft).map(([sec,ids])=>`<p><b>SECTION ${esc(sec)}</b> · ${esc(ids.join(', ')||'No tables')}</p>`).join('');const groups={};for(const t of config.tables.slice().sort((a,b)=>a.id.localeCompare(b.id,undefined,{numeric:true}))){const group=/^Bar /i.test(t.id)?'BAR':t.id.match(/^[A-Za-z]+/)[0];(groups[group]??=[]).push(t);} $('mapTableChoices').innerHTML=Object.entries(groups).map(([group,tables])=>`<fieldset class="secondary-category"><legend>${esc(group)}</legend><div class="secondary-grid">${tables.map(t=>`<button data-map-table="${esc(t.id)}" class="pick-btn"><strong>${esc(t.id)}</strong><small>${owner(t.id)?'SECTION '+esc(owner(t.id)):'UNASSIGNED'}</small></button>`).join('')}</div></fieldset>`).join('');$('mapTableChoices').querySelectorAll('[data-map-table]').forEach(button=>button.onclick=()=>{const id=button.dataset.mapTable,target=$('mapSection').value;for(const sec of Object.keys(draft))draft[sec]=draft[sec].filter(t=>t!==id);if(target)draft[target].push(id);dirty=true;draw();});};
const load=()=>{draft=JSON.parse(JSON.stringify(config.formations[$('mapTemplate').value]));base=JSON.stringify(draft);dirty=false;$('mapSection').innerHTML='<option value="">UNASSIGNED · remove from section</option>'+Object.keys(draft).map(sec=>`<option value="${esc(sec)}">SECTION ${esc(sec)}</option>`).join('');$('mapSection').selectedIndex=1;draw();};$('mapTemplate').onchange=()=>{if(dirty&&!confirm('Discard unsaved table changes?')){$('mapTemplate').value=loadedName;return;}loadedName=$('mapTemplate').value;load();};let loadedName=$('mapTemplate').value;$('reloadMap').onclick=load;load();$('saveTemplate').onclick=async()=>{const name=$('mapTemplate').value,form=JSON.parse(JSON.stringify(draft));try{await connection.updateConfig(c=>{if(JSON.stringify(c.formations[name])!==base&&JSON.stringify(c.formations[name])!==JSON.stringify(form))throw Error('This table map changed on another device. Reload saved before editing.');c.formations[name]=form;return c;});if(shiftBoard().formation===name){const mapping={};for(const [sec,ids]of Object.entries(form)){const row=shiftBoard().rows.find(r=>!r.cut&&r.section.split(' / ').includes(sec));if(row)ids.forEach(id=>mapping[id]=row.id);}await send('ASSIGNMENTS',{mapping,expectedFormation:name},{keepDialog:true,message:'SECTION TABLES UPDATED'});}base=JSON.stringify(form);dirty=false;toast('FORMATION TABLES SAVED');}catch(error){toast(error.message);}};}

async function verifyPassword(value){const auth=config.managerAuth;if(!auth)throw Error('Manager access is not configured.');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(value),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:Uint8Array.from(auth.salt.match(/../g).map(x=>parseInt(x,16))),iterations:auth.iterations,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join('')===auth.hash;}
function passwordDialog(){openDialog('Edit Manager Password','<label for="oldPassword">Current manager password</label><input type="password" id="oldPassword" autocomplete="current-password" class="field"><label for="newPassword">New password · at least 8 characters</label><input type="password" id="newPassword" autocomplete="new-password" class="field"><label for="confirmPassword">Confirm new password</label><input type="password" id="confirmPassword" autocomplete="new-password" class="field"><button id="savePassword" class="primary full">UPDATE SHARED PASSWORD</button>');$('savePassword').onclick=async()=>{try{if(!await verifyPassword($('oldPassword').value))throw Error('Current password does not match.');const value=$('newPassword').value;if(value.length<8||value!==$('confirmPassword').value)throw Error('Use matching passwords with at least 8 characters.');const salt=crypto.getRandomValues(new Uint8Array(16)),key=await crypto.subtle.importKey('raw',new TextEncoder().encode(value),'PBKDF2',false,['deriveBits']),iterations=150000,bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations,hash:'SHA-256'},key,256),hex=a=>[...new Uint8Array(a)].map(x=>x.toString(16).padStart(2,'0')).join('');await connection.updateConfig(c=>{c.managerAuth={salt:hex(salt),iterations,hash:hex(bits)};return c;});managerAuthorized=false;role='Front Host';$('role').value=role;closeDialog();toast('PASSWORD UPDATED · SIGN IN AGAIN');}catch(e){toast(e.message);}};}
function reservationDialog(){communications.openReservations();}
async function createManagerGate(value){openDialog('First Manager Setup','<p class="helper">Create a new shared manager password for this app. The old app password is not copied.</p><form id="firstPasswordForm"><label for="firstPassword">New manager password · at least 8 characters</label><input id="firstPassword" type="password" autocomplete="new-password" class="field" required><label for="firstPasswordConfirm">Confirm password</label><input id="firstPasswordConfirm" type="password" autocomplete="new-password" class="field" required><button class="primary full">CREATE MANAGER ACCESS</button></form>');$('firstPasswordForm').onsubmit=async event=>{event.preventDefault();try{const password=$('firstPassword').value;if(password.length<8||password!==$('firstPasswordConfirm').value)throw Error('Use matching passwords with at least 8 characters.');const salt=crypto.getRandomValues(new Uint8Array(16)),iterations=150000,key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations,hash:'SHA-256'},key,256),hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join(''),auth={salt:hex(salt),iterations,hash:hex(bits)};await connection.updateConfig(c=>{if(c.managerAuth)return undefined;c.managerAuth=auth;return c;});managerAuthorized=true;role=value;$('role').value=value;closeDialog();communications.publishPresence();finishRole();toast('MANAGER ACCESS CREATED');}catch(e){toast(e.message);}};}
async function changeRole(value){if(['Manager','Owner'].includes(value)){if(!config.managerAuth){$('role').value=role;return createManagerGate(value);}openDialog(value+' Access','<form id="roleForm"><label for="managerPassword">Manager password</label><input id="managerPassword" type="password" autocomplete="current-password" class="field" required><button class="primary full" type="submit">ENTER '+esc(value.toUpperCase())+'</button></form>');$('roleForm').onsubmit=async e=>{e.preventDefault();try{if(!await verifyPassword($('managerPassword').value))throw Error('Password does not match.');managerAuthorized=true;role=value;$('role').value=role;closeDialog();communications?.publishPresence();finishRole();toast(value+' ready');}catch(e){toast(e.message);}};$('role').value=role;}else{managerAuthorized=false;role=value;$('role').value=role;communications?.publishPresence();finishRole();}}
async function checkDay(){if(!state||!connection?.connected||connection.busy)return;if(C.dayAt(connection.now())>state.day)try{await send('DAILY_RESET',{}, {message:'NEW DAY · BOARD + FLOOR READY'});}catch(_){};}
async function boot(){initClassic();document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>pane(b.dataset.pane));$('modalClose').onclick=closeDialog;$('shift').value=selectedShift;$('shift').onchange=()=>{selectedShift=$('shift').value;localStorage.setItem('fz_next_shift',selectedShift);seatDraft={};lastPanel='';render();};$('role').onchange=()=>changeRole($('role').value);const menuGroups=[['SHIFT & SECTIONS',['setup','join','beeper','map','formation','correct']],['STAFF',['roster','cut']],['DATA & COMMUNICATION',['reservations','chat','shout','password','bar','undo','pending','clearAM','clearPM']]];$('operations').innerHTML=menuGroups.map(([title,ids])=>'<section class="menu-group"><div class="menu-group-title">'+title+'</div><div class="menu-grid">'+operations.filter(([id])=>ids.includes(id)).map(([id,title,desc])=>`<button class="op-card ${id.startsWith('clear')?'danger':''}" data-op="${id}"><strong>${title}</strong><small>${desc}</small></button>`).join('')+'</div></section>').join('');document.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>operation(b.dataset.op));$('chatOpen').onclick=()=>communications?.openChat();
 const options=await fetch('./app-config.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('App configuration missing.');return r.json();});connection=new HostConnection(options);
 connection.onConfig=c=>{if(lastAuthHash&&lastAuthHash!==c.managerAuth?.hash){managerAuthorized=false;role='Front Host';$('role').value=role;}lastAuthHash=c.managerAuth?.hash||'';config=c;render();};connection.onState=s=>{state=s;render();};connection.onStatus=status=>{if(status.connected&&!wasConnected)communications?.publishPresence();wasConnected=!!status.connected;$('connection').className='connection '+(status.connected&&status.ready?'live':'offline');$('connection').textContent=status.connected&&status.ready?'LIVE':'OFFLINE / CONNECTING';document.querySelectorAll('#tablePanel button,#seatForm select,#seatForm input,#wizardNext,#seatNext,[data-row-seat],[data-skip],[data-bar-toggle]').forEach(b=>b.disabled=status.busy||!status.connected||!status.ready||!!(b.dataset.rowSeat&&shiftBoard()?.rows.find(r=>r.id===b.dataset.rowSeat)?.cut));if(status.error)notice(status.error,'error');else if(status.busy)notice('SAVING · waiting for the database…','saving');else if(status.connected&&status.ready)notice('LIVE · ready for host operations.');else notice('Connection not ready. Saves are blocked until LIVE.','error');};connection.start();communications=new HostCommunications({connection,getRole:()=>role,isManager:manager,openDialog,closeDialog,toast,escape:esc,onReservationsChange:()=>renderMap()});communications.start();setInterval(checkDay,15000);window.addEventListener('online',checkDay);setTimeout(checkDay,2000);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
window.FZHostApp={get state(){return state;},get config(){return config;},get connection(){return connection;},send,operation,pane};
boot().catch(e=>{notice(e.message,'error');toast(e.message);});
